import { managementHtml } from "./management-presentation";
import { reliability, reliabilityTrend, qualityIssues, overdueRecommendation } from "./engineering-insights";
import { analyseDashboard, dashboardFilters, chart, paretoChart, analyticsStyle } from "./dashboard-analytics";
import { canViewCompanyPage, isCompanyAdmin } from "./company-navigation-access";
import currentApp from "./router-company-admin-demo-ui";

interface ExecutionContext { waitUntil(promise: Promise<unknown>): void; passThroughOnException(): void; }
interface ScheduledController { scheduledTime:number; cron:string; noRetry():void; }
interface Env { DB:D1Database; [key:string]:unknown; }
type Row = Record<string, unknown>;
type AdminSession = { companyId:number; accountId:number; fullName:string; email:string; role:string; companyName:string; licenceStatus:string; licenceExpires:string; };

const COOKIE="sas_contractor_v2";
const enc=new TextEncoder();
const esc=(v:unknown)=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]||c));
const num=(v:unknown,f=0)=>{const n=Number(v);return Number.isFinite(n)?n:f};
const low=(v:unknown)=>String(v??"").toLowerCase();
const fmt=(v:number,d=1)=>v.toLocaleString("en-ZA",{maximumFractionDigits:d});
const pct=(v:number)=>`${Number.isFinite(v)?v.toFixed(1):"0.0"}%`;
function getCookie(req:Request){for(const p of (req.headers.get("cookie")||"").split(";")){const i=p.indexOf("=");if(i>-1&&p.slice(0,i).trim()===COOKIE)return p.slice(i+1).trim()}return ""}
async function sha256(v:string){return Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",enc.encode(v))),b=>b.toString(16).padStart(2,"0")).join("")}
async function first(env:Env,sql:string,binds:unknown[]=[]){try{return await env.DB.prepare(sql).bind(...binds).first<Row>()}catch{return null}}
async function all(env:Env,sql:string,binds:unknown[]=[]){try{return ((await env.DB.prepare(sql).bind(...binds).all<Row>()).results||[])}catch{return []}}
async function session(req:Request,env:Env):Promise<AdminSession|null>{
 const token=getCookie(req);if(!token)return null;
 const r=await first(env,`SELECT s.company_id companyId,s.account_id accountId,s.expires_at sessionExpires,a.email,a.full_name fullName,COALESCE(NULLIF(s.active_role,''),a.role) role,a.status accountStatus,c.name companyName,c.licence_status licenceStatus,c.expires_at licenceExpires,c.grace_days graceDays FROM contractor_sessions s JOIN contractor_accounts a ON a.id=s.account_id AND a.company_id=s.company_id JOIN companies c ON c.id=s.company_id WHERE s.token_hash=? LIMIT 1`,[await sha256(token)]);
 if(!r||low(r.accountStatus)!=="active"||!Number.isFinite(new Date(String(r.sessionExpires)).getTime())||new Date(String(r.sessionExpires)).getTime()<Date.now())return null;
 const st=low(r.licenceStatus),end=new Date(String(r.licenceExpires)).getTime()+num(r.graceDays)*86400000;if(!["active","trial"].includes(st)||!Number.isFinite(end)||Date.now()>end)return null;
 return {companyId:num(r.companyId),accountId:num(r.accountId),email:String(r.email||""),fullName:String(r.fullName||""),role:String(r.role||""),companyName:String(r.companyName||"Company Workspace"),licenceStatus:String(r.licenceStatus||""),licenceExpires:String(r.licenceExpires||"")};
}
function html(body:string,status=200){return new Response(body,{status,headers:{"content-type":"text/html; charset=utf-8","cache-control":"private, no-store","x-frame-options":"DENY","referrer-policy":"same-origin","content-security-policy":"default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'"}})}
function redirect(url:string){return new Response(null,{status:303,headers:{location:url,"cache-control":"no-store"}})}

async function data(env:Env,s:AdminSession){
 const cid=s.companyId;
 const machines=await all(env,"SELECT id,fleet_number fleet,category,site,status,operating_hours hours,next_service_hours nextService FROM machines WHERE company_id=? ORDER BY fleet_number",[cid]);
 const events=await all(env,"SELECT id,fleet_number fleet,severity,event_type eventType,closed_at closedAt,system_name system,component,description,opened_at openedAt,downtime_hours downtime,status,action,spares_status spares FROM events WHERE company_id=? ORDER BY id DESC",[cid]);
 const production=await all(env,"SELECT id,report_date reportDate,fleet_number fleet,shift_hours shiftHours,planned_downtime plannedDowntime,unplanned_downtime unplannedDowntime,operating_hours operatingHours,productive_hours productiveHours,tonnes FROM production_records WHERE company_id=? ORDER BY report_date DESC,id DESC",[cid]);
 const settings=await first(env,"SELECT daily_production_target dailyTarget,availability_target availabilityTarget,operating_hours operatingHours FROM company_settings_v3 WHERE company_id=? LIMIT 1",[cid]);
 const users=await all(env,"SELECT id,email,full_name fullName,role,status FROM contractor_accounts WHERE company_id=? ORDER BY id",[cid]);
 return {machines,events,production,settings,users};
}
function calc(d:Awaited<ReturnType<typeof data>>){
 const latest=String(d.production[0]?.reportDate||"");const day=d.production.filter(r=>String(r.reportDate)===latest);
 const scheduled=day.reduce((a,r)=>a+num(r.shiftHours),0),planned=day.reduce((a,r)=>a+num(r.plannedDowntime),0),unplanned=day.reduce((a,r)=>a+num(r.unplannedDowntime),0),operating=day.reduce((a,r)=>a+num(r.operatingHours),0),productive=day.reduce((a,r)=>a+num(r.productiveHours),0),tonnes=day.reduce((a,r)=>a+num(r.tonnes),0),available=Math.max(0,scheduled-planned-unplanned);
 const availability=scheduled?available/scheduled*100:0,utilisation=available?operating/available*100:0;
 const opMachines=d.machines.filter(m=>low(m.status)==="operating").length,down=d.machines.filter(m=>low(m.status)==="down").length,attention=d.machines.filter(m=>["attention","warning","maintenance"].includes(low(m.status))).length;
 const open=d.events.filter(e=>low(e.status)!=="closed");
 const maintenance=d.machines.map(m=>({fleet:String(m.fleet),due:m.nextService==null?null:num(m.nextService)-num(m.hours),task:"Scheduled service",site:String(m.site||""),status:String(m.status||"")})).filter(x=>x.due!==null).sort((a,b)=>num(a.due)-num(b.due));
 return {latest,scheduled,planned,unplanned,available,operating,productive,tonnes,availability,utilisation,opMachines,down,attention,open,maintenance};
}
function pareto(events:Row[]){const map=new Map<string,number>();for(const e of events){const k=String(e.system||"Other");map.set(k,(map.get(k)||0)+num(e.downtime))}return [...map.entries()].sort((a,b)=>b[1]-a[1]).slice(0,6)}
function nav(active:string,s:AdminSession){
 const items=[
  ["dashboard","▦","Overview"],
  ["fleet","▰","Fleet & Machines"],
  ["maintenance","⚒","Faults & Maintenance"],
  ["reports-live","▥","Reports & Analytics"],
  ["users","♙","Administration"],
  ["setup","⚙","Company Settings"]
 ];
 return `<aside class="side"><div class="brand"><img src="/sindane-logo.png" alt="Sindane Asset Solutions"><div><b>TMM Asset Health</b><small>Company Admin</small></div></div><nav>${items.map(([id,ic,label])=>{const href=id==="trial-demo"?"/trial-demo":id==="reports-admin"?"/contractor?view=reports-admin":`/contractor?view=${id}`;return `<a class="${active===id?"active":""}" href="${href}"><span>${ic}</span>${label}</a>`}).join("")}</nav><div class="companybox"><small>COMPANY ADMIN</small><b>${esc(s.companyName)}</b><span>${esc(s.licenceStatus)} licence</span></div><div class="userbox"><b>${esc(s.fullName)}</b><small>${esc(s.email)}</small><a href="/contractor-logout">Log out</a></div></aside>`;
}
function shell(active:string,title:string,s:AdminSession,content:string){return `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} · TMM Asset Health</title>${css()}</head><body><div class="app">${nav(active,s)}<main class="main"><header class="top"><div><b>TMM Asset Health</b><small>Mine. Contractor. Workshop. One Solution.</small></div><div class="topright"><span>${esc(s.companyName)}</span><span class="avatar">${esc((s.fullName||"A").split(/\s+/).map(x=>x[0]).slice(0,2).join("").toUpperCase())}</span></div></header>${content}</main></div></body></html>`}
function head(kicker:string,title:string,buttons=""){return `<div class="pagehead"><div><small>${esc(kicker)}</small><h1>${esc(title)}</h1></div><div class="actions">${buttons}<button onclick="window.print()">Print</button></div></div>`}
function card(label:string,value:string,note:string){return `<article class="metric"><small>${esc(label)}</small><b>${esc(value)}</b><span>${esc(note)}</span></article>`}
function table(title:string,sub:string,heads:string[],rows:string[][]){return `<section class="panel tablecard"><div class="panelhead"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div></div><div class="tablewrap"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join(""):`<tr><td colspan="${heads.length}" class="empty">No records available yet.</td></tr>`}</tbody></table></div></section>`}
function paretoHtml(items:[string,number][]){const max=Math.max(1,...items.map(x=>x[1]));return items.length?items.map(([k,v])=>`<div class="pareto"><b>${esc(k)}</b><span><i style="width:${v/max*100}%"></i></span><strong>${v.toFixed(1)} h</strong></div>`).join(""):`<p class="empty">Breakdown data will build the Pareto automatically.</p>`}
function action(n:number,title:string,text:string,tone="MEDIUM"){return `<div class="actionitem"><b>${n}</b><div><strong>${esc(title)}</strong><span>${esc(text)}</span></div><em>${esc(tone)}</em></div>`}

async function dashboard(req:Request,env:Env,s:AdminSession){
 const d=await data(env,s),f=dashboardFilters(new URL(req.url)),a=analyseDashboard(d,f),admin=isCompanyAdmin(s.role),rate=await analyticsRate(env,s);
 if(new URL(req.url).searchParams.get('download')==='csv'){
   const cell=(v:unknown)=>{let value=String(v??'');if(typeof v==='string'&&/^[=+@-]/.test(value))value="'"+value;return '"'+value.replace(/"/g,'""')+'"';};
   const rows=[['Date','Fleet','Shift hours','Operating hours','Planned downtime','Unplanned downtime','Tonnes'],...a.production.map(r=>[r.reportDate,r.fleet,r.shiftHours,r.operatingHours,r.plannedDowntime,r.unplannedDowntime,r.tonnes])];
   return new Response(rows.map(r=>r.map(cell).join(',')).join('\r\n'),{headers:{'content-type':'text/csv; charset=utf-8','content-disposition':'attachment; filename="fleet-performance.csv"','cache-control':'private, no-store'}});
 }
 const option=(v:string,current:string)=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`;
 const download=new URL(req.url);download.searchParams.set('download','csv');
 const today=new Date().toISOString().slice(0,10),week=new Date(Date.now()-6*86400000).toISOString().slice(0,10);
 const preset=(from:string,label:string)=>{const u=new URL(req.url);u.searchParams.delete("download");u.searchParams.set("from",from);u.searchParams.set("to",today);return `<a href="${esc(u.pathname+u.search)}">${label}</a>`;};
 const filter=`<div class="role-links">${preset(today,"Today")}${preset(week,"Last 7 days")}${preset(today.slice(0,7)+"-01","This month")}</div><form class="panel dashboard-filters" method="get" action="/contractor"><input type="hidden" name="view" value="dashboard"><label>From<input type="date" name="from" value="${f.from}" required></label><label>To<input type="date" name="to" value="${f.to}" required></label><label>Site<select name="site"><option value="">All sites</option>${[...new Set(d.machines.map(m=>String(m.site||'')))].filter(Boolean).map(v=>option(v,f.site)).join('')}</select></label><label>Equipment<select name="fleet"><option value="">All equipment</option>${d.machines.map(m=>option(String(m.fleet),f.fleet)).join('')}</select></label><button class="primary">Apply filters</button><a href="/contractor">Reset</a></form>`;
 const kpi=(v:number|null)=>v===null?'—':pct(v);
 const dates=a.trend.map(t=>t.date),count=a.trend.length;
 const missing=a.machines.length-new Set(a.production.filter(r=>String(r.reportDate)===f.to).map(r=>String(r.fleet))).size;
 const links=admin?`<a class="btn" href="/contractor?view=fleet">Register machines</a><a class="btn" href="/oem-connections">Connect machine data</a><a class="btn" href="/telemetry">Live machine readings</a>`:`<a class="btn" href="/contractor?view=breakdowns">Review breakdowns</a><a class="btn" href="/contractor?view=fleet">Analyse equipment</a>`;
 const charts=`<div class="grid2">${chart('Availability and utilisation trends',dates,[{name:'Availability',color:'#2563eb',values:a.trend.map(t=>t.availability)},{name:'Utilisation',color:'#0f766e',values:a.trend.map(t=>t.utilisation)}],'line','%')}${chart('Production actual versus target',dates,[{name:'Actual tonnes',color:'#294467',values:a.trend.map(t=>t.tonnes)},...(a.target>0&&!f.site&&!f.fleet?[{name:'Company daily target',color:'#d97706',values:a.trend.map(()=>a.target)}]:[])],'bar',' t')}${chart('Downtime trend',dates,[{name:'Planned',color:'#64748b',values:a.trend.map(t=>t.planned)},{name:'Unplanned',color:'#dc2626',values:a.trend.map(t=>t.unplanned)}],'bar',' h')}${paretoChart('Downtime Pareto by cause',a.causePareto)}${paretoChart('Downtime Pareto by machine',a.machinePareto)}<section class="panel"><h2>Recurring faults</h2>${a.repeat.length?a.repeat.map(([key,count])=>`<div class="line"><b>${esc(key)}</b><span>Recorded events</span><strong>${count}</strong></div>`).join(''):'<p>No recurring faults recorded for this period.</p>'}<h2>Maintenance due / overdue</h2><p>Current hour meters for selected equipment.</p>${a.maintenance.filter(m=>m.remaining<=50).slice(0,5).map(m=>`<div class="line"><b>${esc(m.fleet)}</b><span>${m.remaining<=0?'Overdue':'Due soon'}</span><strong>${m.remaining.toFixed(1)} h remaining</strong></div>`).join('')||'<p>No services due within 50 hours.</p>'}<p><a href="/contractor?view=maintenance">View full maintenance planner →</a></p></section></div>`;
 const overview=`<div class="metrics">${card('Availability',kpi(a.availability),'Weighted by scheduled hours')}${card('Utilisation',kpi(a.utilisation),'Operating ÷ available hours')}${card('Recorded production',fmt(a.tonnes,0)+' t',a.target&&!f.site&&!f.fleet?`${count} reporting days · target ${fmt(a.target*count,0)} t`:'Company target applies to the full fleet')}${card('Downtime',a.production.length?fmt(a.planned+a.unplanned)+' h':'—','Daily reports: planned + unplanned')}${admin?card('Legacy report gaps',String(Math.max(0,missing)),`Legacy daily-report records on ${f.to}; not a telemetry connectivity measure`):card('Recurring fault groups',String(a.repeat.length),'Repeated fleet / system events')}</div>`;
 const visualIcon=(kind:string)=>{const paths:Record<string,string>={truck:'<path d="M3 8h12v9H3zM15 11h4l3 3v3h-7z"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',tool:'<path d="M21 6a6 6 0 0 1-8 7L6 20a2 2 0 0 1-3-3l7-7a6 6 0 0 1 7-8l-4 4 4 4z"/>',pulse:'<path d="M2 12h5l3-7 4 14 3-7h5"/>',trend:'<path d="M3 19V5M3 19h18M6 15l5-5 4 3 6-7M17 6h4v4"/>',shield:'<path d="M12 2 20 5v6c0 5-3 8-8 11-5-3-8-6-8-11V5z"/><path d="m8 12 3 3 5-6"/>'};return '<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[kind]||paths.pulse)+'</svg>'};
 const statTile=(kind:string,label:string,value:string,detail:string,tone:string)=>'<div class="command-tile '+tone+'"><div class="command-icon">'+visualIcon(kind)+'</div><div><span>'+esc(label)+'</span><strong>'+esc(value)+'</strong><small>'+esc(detail)+'</small></div></div>';
 const commandCentre='<section class="command-centre" aria-label="Fleet command centre"><div class="command-heading"><div><small>ASSET INTELLIGENCE / LIVE COMPANY RECORDS</small><h2>Fleet command centre</h2><p>Company-specific operational snapshot · '+esc(f.from)+' to '+esc(f.to)+'</p></div><div class="command-pill"><span class="command-dot"></span> '+(a.machines.length?'Registered fleet':'Awaiting fleet registration')+'</div></div><div class="command-grid">'+statTile('truck','Registered machines',String(a.machines.length),'From fleet register','blue')+statTile('pulse','Fleet availability',kpi(a.availability),'Calculated from recorded hours','teal')+statTile('clock','Operating hours',a.production.length?fmt(a.production.reduce((sum,r)=>sum+num(r.operatingHours),0))+' h':'—','Daily operating records','blue')+statTile('tool','Service overdue',String(a.maintenance.filter(m=>m.remaining<=0).length),'Based on available hour meters','amber')+statTile('trend','Recorded production',fmt(a.tonnes,0)+' t','Recorded daily reports','teal')+statTile('shield','Recurring fault groups',String(a.repeat.length),'Verified event history','amber')+'</div><div class="command-bottom"><div class="command-legend"><span><i class="key-blue"></i> Operating records</span><span><i class="key-teal"></i> Performance</span><span><i class="key-amber"></i> Maintenance</span></div><p>No simulated telemetry. Missing readings are shown as unavailable.</p></div></section>';
 const equipmentBoard='<section class="panel fleet-visual"><div class="panelhead"><div><small class="section-eyebrow">EQUIPMENT OPERATIONS</small><h2>Fleet status & service watch</h2><p>Registered machines only · select an asset to review its history</p></div><a class="btn" href="/contractor?view=fleet">Fleet register</a></div>'+(a.machines.length?'<div class="equipment-grid">'+a.machines.slice(0,12).map(m=>{const status=low(m.status),tone=status==='operating'?'ok':status==='down'?'critical':'caution';const service=a.maintenance.find(x=>String(x.fleet)===String(m.fleet));const remaining=service&&Number.isFinite(service.remaining)?service.remaining:null;const href='/contractor?view=machine-history&fleet='+encodeURIComponent(String(m.fleet||''));return '<a class="equipment-card" href="'+esc(href)+'"><div class="equipment-symbol">'+visualIcon('truck')+'</div><div class="equipment-info"><strong>'+esc(m.fleet)+'</strong><small>'+esc(m.category||'Machine')+' · '+esc(m.site||'Site not specified')+'</small></div><span class="equipment-state '+tone+'">'+esc(m.status||'Unknown')+'</span><div class="equipment-meta"><span>Hour meter <b>'+ (m.hours==null?'Unavailable':esc(fmt(num(m.hours))+' h'))+'</b></span><span>Service remaining <b>'+(remaining==null?'Unavailable':esc(fmt(remaining)+' h'))+'</b></span></div></a>'}).join('')+'</div>':'<div class="fleet-empty">'+visualIcon('truck')+'<div><strong>No registered equipment yet</strong><p>Register a real machine to activate the fleet status cards and service indicators.</p><a href="/contractor?view=fleet">Open Fleet registration</a></div></div>')+'</section>';
 const serviceGauges='<section class="panel service-watch"><div class="panelhead"><div><small class="section-eyebrow">MAINTENANCE INTELLIGENCE</small><h2>Service hour gauges</h2><p>Calculated from recorded hour meters and next-service thresholds</p></div></div>'+(a.maintenance.length?'<div class="gauge-grid">'+a.maintenance.slice(0,6).map(m=>{const remaining=num(m.remaining),next=num(m.nextService),total=250;const fraction=Math.max(0,Math.min(1,remaining/total));const circumference=2*Math.PI*42;const stroke=remaining<=0?'#f97373':remaining<=50?'#f4bd63':'#38d4bd';return '<div class="gauge-card"><svg viewBox="0 0 120 120" role="img" aria-label="'+esc(m.fleet)+' service remaining '+esc(fmt(remaining))+' hours"><circle cx="60" cy="60" r="42" fill="none" stroke="#e7eef5" stroke-width="10"/><circle cx="60" cy="60" r="42" fill="none" stroke="'+stroke+'" stroke-width="10" stroke-linecap="round" stroke-dasharray="'+(circumference*fraction).toFixed(2)+' '+circumference.toFixed(2)+'" transform="rotate(-90 60 60)"/><text x="60" y="58" text-anchor="middle" font-size="20" font-weight="800" fill="#122a49">'+esc(fmt(remaining,0))+'</text><text x="60" y="73" text-anchor="middle" font-size="10" fill="#60768c">hours left</text></svg><strong>'+esc(m.fleet)+'</strong><small>Next service '+esc(fmt(next))+' h</small></div>'}).join('')+'</div>':'<div class="fleet-empty"><div><strong>Service gauges awaiting registered hour meters</strong><p>No service interval or meter values are invented.</p></div></div>')+'</section>';
 const adminPanel=admin?`<section class="panel"><h2>Administration overview</h2><p>${a.machines.length} selected machines · ${d.users.filter(u=>low(u.status)==='active').length} active company users · ${a.maintenance.filter(m=>m.remaining<=0).length} overdue services</p><p>Machine registration is the only routine manual setup. Live monitoring uses incoming machine data; historical report figures below may still depend on legacy records until telemetry reporting is fully connected.</p></section>`:'';
 const quickLinks='<nav class="command-actions" aria-label="Dashboard shortcuts"><a href="/contractor?view=fleet">Fleet & equipment</a><a href="/contractor?view=breakdowns">Breakdowns</a><a href="/contractor?view=maintenance">Maintenance</a><a href="/contractor?view=reports-live">Reports</a><a href="/contractor?view=machine-history">Machine history</a></nav>';
 const topKpis='<div class="command-kpis">'+statTile('trend','Production',fmt(a.tonnes,0)+' t','Recorded tonnes','teal')+statTile('pulse','Availability',kpi(a.availability),'Recorded shift hours','blue')+statTile('clock','Utilisation',kpi(a.utilisation),'Operating / available hours','amber')+statTile('shield','Breakdowns',String(a.events.length),'Recorded events','red')+'</div>';
 const summaryCharts='<div class="command-chart-grid">'+chart('Production performance',dates,[{name:'Actual tonnes',color:'#38bdf8',values:a.trend.map(t=>t.tonnes)},...(a.target>0&&!f.site&&!f.fleet?[{name:'Daily target',color:'#fbbf24',values:a.trend.map(()=>a.target)}]:[])],'bar',' t')+chart('Availability & utilisation',dates,[{name:'Availability',color:'#38bdf8',values:a.trend.map(t=>t.availability)},{name:'Utilisation',color:'#a78bfa',values:a.trend.map(t=>t.utilisation)}],'line','%')+'</div>';
 const servicePreview='<section class="panel command-service"><div class="panelhead"><div><h2>Service watch</h2><p>Next service by recorded engine hours</p></div><a href="/contractor?view=maintenance">View planner</a></div>'+(a.maintenance.length?'<div class="service-list">'+a.maintenance.slice(0,4).map(m=>'<div><strong>'+esc(m.fleet)+'</strong><span>'+esc(fmt(m.remaining))+' h remaining</span></div>').join('')+'</div>':'<p class="command-muted">No service readings available.</p>')+'</section>';
 const faultPreview='<section class="panel command-fault"><div class="panelhead"><div><h2>Downtime by cause</h2><p>Recorded breakdown history</p></div><a href="/contractor?view=breakdowns">View breakdowns</a></div>'+(a.causePareto.length?paretoChart('Downtime causes',a.causePareto):'<p class="command-muted">No breakdown causes recorded.</p>')+'</section>';
 const body=`<section class="content command-layout">${head(s.companyName,'Fleet Performance Dashboard',`<a class="btn" href="${esc(download.pathname+download.search)}">Export CSV</a>`)}<div class="command-subtitle">Production · Equipment health · Maintenance <span>${esc(f.from)} — ${esc(f.to)}</span></div>${quickLinks}${topKpis}${summaryCharts}<div class="command-secondary">${faultPreview}${servicePreview}</div><section class="command-equipment">${equipmentBoard}</section><details class="command-details"><summary>Filters & reporting period</summary>${filter}</details><details class="command-details"><summary>Engineering analytics & reliability</summary>${overview}${charts}${reliabilityPanel(d,f)}</details><details class="command-details"><summary>Administration, data quality & advanced tools</summary><div class="role-links">${links}<a class="btn" href="/contractor?view=recommendations">Recommendations</a><a class="btn" href="/contractor?view=data-quality">Data quality</a><a class="btn" href="/contractor?view=management-presentation">Management presentation</a></div>${serviceGauges}${admin?adminPanel:''}<section class="panel"><h2>Estimated downtime cost</h2><p>${rate>0?`R ${fmt((a.planned+a.unplanned)*rate,2)} estimated`:'Enter a cost rate to estimate downtime cost.'}</p>${admin?`<form method="post" action="/company-admin/analytics-settings"><input type="hidden" name="csrf" value="${await sha256(getCookie(req))}"><label>Cost per machine downtime hour (ZAR)<input name="rate" type="number" min="0" max="1000000000" step="0.01" value="${rate}" required></label><button class="primary">Save company rate</button></form>`:''}</section>${await recommendationSummary(env,s)}</details></section>`;
 return html(shell('dashboard',admin?'Admin Dashboard':'Engineer Dashboard',s,body).replace('<body','<body class="dashboard-modern"').replace('</head>',analyticsStyle+`<style>\n/* Modern light contractor overview: presentation-only; preserves all existing actions. */\n.dashboard-modern .content{max-width:1560px;margin-inline:auto;padding:clamp(16px,2vw,32px)}\n.dashboard-modern .hero{padding:22px 26px;border-radius:15px;background:linear-gradient(115deg,#14253f,#334e73);box-shadow:0 8px 22px rgba(19,40,69,.08)}\n.dashboard-modern .hero h2{font-size:clamp(22px,2vw,30px);line-height:1.2;letter-spacing:-.025em}\n.dashboard-modern .role-links{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}\n.dashboard-modern .role-links .btn{border-radius:9px;padding:10px 13px}\n.dashboard-modern .dashboard-filters{border-radius:14px;padding:17px 19px}\n.dashboard-modern .metrics{gap:12px;margin:14px 0}\n.dashboard-modern .metrics>*{border-radius:13px;box-shadow:0 3px 12px rgba(15,35,65,.045);border:1px solid #e1e8f0;min-width:0}\n.dashboard-modern .grid2{gap:14px;align-items:start}\n.dashboard-modern .grid2>.panel{border-radius:14px;min-width:0;padding:19px;border:1px solid #e1e8f0;box-shadow:0 3px 12px rgba(15,35,65,.045)}\n.dashboard-modern .grid2>.panel h2{font-size:16px;line-height:1.35}\n.dashboard-modern .grid2>.panel .line{gap:12px}\n.dashboard-modern .content>.panel{border-radius:14px;margin-top:14px;padding:19px}\n@media(max-width:800px){.dashboard-modern .content{padding:14px}.dashboard-modern .hero{padding:20px}.dashboard-modern .grid2{grid-template-columns:minmax(0,1fr)}}
/* Dashboard shell: override legacy wrappers that displace the navigation. */\nhtml:has(body.dashboard-modern){margin:0!important;padding:0!important;overflow-x:hidden!important}\nbody.dashboard-modern{margin:0!important;padding:0!important;position:static!important;transform:none!important;overflow-x:hidden!important;min-height:100vh!important}\nbody.dashboard-modern .app{display:grid!important;grid-template-columns:255px minmax(0,1fr)!important;grid-template-rows:minmax(100vh,auto)!important;align-items:start!important;position:relative!important;inset:auto!important;transform:none!important;margin:0!important;padding:0!important;width:100%!important;max-width:none!important;min-height:100vh!important}\nbody.dashboard-modern .side{grid-column:1!important;grid-row:1!important;position:sticky!important;top:0!important;left:auto!important;bottom:auto!important;transform:none!important;margin:0!important;width:255px!important;max-width:255px!important;height:100vh!important;min-height:0!important;overflow-y:auto!important;z-index:10!important}\nbody.dashboard-modern .main{grid-column:2!important;grid-row:1!important;display:block!important;position:relative!important;inset:auto!important;transform:none!important;margin:0!important;padding:0!important;width:100%!important;min-width:0!important;max-width:none!important;overflow:visible!important}\nbody.dashboard-modern .top{display:flex!important;position:sticky!important;top:0!important;left:auto!important;right:auto!important;bottom:auto!important;transform:none!important;margin:0!important;width:100%!important;min-height:68px!important;height:auto!important;z-index:9!important}\nbody.dashboard-modern .content{display:block!important;position:relative!important;inset:auto!important;transform:none!important;float:none!important;clear:none!important;width:100%!important;min-width:0!important;max-width:1560px!important;margin:0 auto!important;padding:24px!important}\nbody.dashboard-modern .companybox,body.dashboard-modern .userbox{position:static!important;left:auto!important;bottom:auto!important;width:auto!important;max-width:100%!important;margin-top:10px!important}\nbody.dashboard-modern .side nav{padding-bottom:20px!important}\nbody.dashboard-modern .grid2{grid-template-columns:repeat(2,minmax(0,1fr))!important}\nbody.dashboard-modern .metrics{grid-template-columns:repeat(auto-fit,minmax(165px,1fr))!important}\nbody.dashboard-modern .panel,body.dashboard-modern .metric{min-width:0!important}\n@media(max-width:900px){body.dashboard-modern .app{grid-template-columns:minmax(0,1fr)!important;grid-template-rows:auto auto!important}body.dashboard-modern .side{grid-column:1!important;grid-row:1!important;position:relative!important;top:auto!important;width:100%!important;max-width:none!important;height:auto!important;overflow:visible!important}body.dashboard-modern .side nav{display:flex!important;flex-wrap:wrap!important;gap:5px!important}body.dashboard-modern .main{grid-column:1!important;grid-row:2!important}body.dashboard-modern .top{position:relative!important}body.dashboard-modern .grid2{grid-template-columns:minmax(0,1fr)!important}body.dashboard-modern .content{padding:16px!important}}\n@media(max-width:540px){body.dashboard-modern .pagehead{align-items:flex-start!important;flex-wrap:wrap!important}body.dashboard-modern .metrics{grid-template-columns:repeat(2,minmax(0,1fr))!important}body.dashboard-modern .top{padding:12px!important}body.dashboard-modern .content{padding:12px!important}}\n/* Responsive layout correction: constrain every grid child to the available viewport. */\nbody.dashboard-modern,body.dashboard-modern *{box-sizing:border-box}\nbody.dashboard-modern .app{grid-template-columns:clamp(205px,17vw,255px) minmax(0,1fr)!important}\nbody.dashboard-modern .side{width:100%!important;max-width:none!important}\nbody.dashboard-modern .main,body.dashboard-modern .content,body.dashboard-modern .top,body.dashboard-modern .pagehead,body.dashboard-modern .hero,body.dashboard-modern .dashboard-filters{min-width:0!important;max-width:100%!important}\nbody.dashboard-modern .content{width:100%!important;padding:clamp(14px,2vw,28px)!important}\nbody.dashboard-modern .top{gap:12px;flex-wrap:wrap;padding:12px clamp(14px,2vw,28px)!important}\nbody.dashboard-modern .topright{min-width:0;max-width:100%;overflow-wrap:anywhere}\nbody.dashboard-modern .pagehead{display:flex;flex-wrap:wrap;align-items:center;gap:12px}\nbody.dashboard-modern .actions,body.dashboard-modern .role-links{max-width:100%;flex-wrap:wrap}\nbody.dashboard-modern .hero{flex-wrap:wrap}\nbody.dashboard-modern .metrics{grid-template-columns:repeat(auto-fit,minmax(min(100%,155px),1fr))!important}\nbody.dashboard-modern .grid2,body.dashboard-modern .grid3{min-width:0!important}\nbody.dashboard-modern .grid2>* ,body.dashboard-modern .grid3>*{min-width:0!important;max-width:100%!important}\nbody.dashboard-modern .panel,body.dashboard-modern .metric{overflow-wrap:anywhere}\nbody.dashboard-modern .dashboard-filters form{display:flex;flex-wrap:wrap;align-items:end;gap:10px}\nbody.dashboard-modern .dashboard-filters input,body.dashboard-modern .dashboard-filters select{max-width:100%}\nbody.dashboard-modern .tablewrap{max-width:100%;overflow-x:auto}\n@media(max-width:1100px){body.dashboard-modern .grid2{grid-template-columns:minmax(0,1fr)!important}}\n@media(max-width:900px){body.dashboard-modern .app{grid-template-columns:minmax(0,1fr)!important}body.dashboard-modern .side{width:100%!important;height:auto!important;position:relative!important}body.dashboard-modern .side nav{display:flex!important;flex-wrap:wrap!important}body.dashboard-modern .content{padding:16px!important}}\n@media(max-width:540px){body.dashboard-modern .metrics{grid-template-columns:repeat(2,minmax(0,1fr))!important}body.dashboard-modern .actions>*{max-width:100%}}\n@media print{body.dashboard-modern .app{display:block!important}body.dashboard-modern .side,body.dashboard-modern .top{display:none!important}body.dashboard-modern .main{display:block!important;width:100%!important}body.dashboard-modern .content{padding:0!important}}\n\n</style>`+'</head>'));
}

async function breakdowns(env:Env,s:AdminSession){const d=await data(env,s),m=calc(d);return html(shell("breakdowns","Breakdowns",s,`<section class="content">${head(`${s.companyName} / BREAKDOWNS`,"Breakdowns",isCompanyAdmin(s.role)?`<a class="btn" href="/contractor?view=daily">+ Quick capture</a>`:`<a class="btn" href="/contractor?view=recommendations">Add recommendation</a>`)}<div class="metrics four">${card("Open events",String(m.open.length),"Current open breakdowns")}${card("Current downtime",`${m.open.reduce((a,e)=>a+num(e.downtime),0).toFixed(1)} h`,"Open events only")}${card("MTTR / recorded repair time",`${d.events.length?d.events.reduce((a,e)=>a+num(e.downtime),0)/d.events.length:0 .toFixed?.(1)} h`,"Average recorded event duration")}${card("Priority watch",String(m.open.filter(e=>["critical","high"].includes(low(e.severity))).length),"Critical + high")}</div>${table("Breakdown register","Fault, system, downtime, priority and recovery status",["Fleet","System","Fault / reason","Opened","Downtime","Priority","Status"],d.events.map(e=>[esc(e.fleet),esc(e.system),esc(e.description),esc(String(e.openedAt).slice(0,16)),`${num(e.downtime).toFixed(1)} h`,esc(e.severity),esc(e.status)]))}</section>`));}

async function maintenance(env:Env,s:AdminSession){const d=await data(env,s),m=calc(d),due=m.maintenance.filter(x=>num(x.due)<50).length,over=m.maintenance.filter(x=>num(x.due)<=0).length;return html(shell("maintenance","Maintenance",s,`<section class="content">${head(`${s.companyName} / MAINTENANCE`,"Maintenance",`<a class="btn" href="/contractor?view=fleet">${isCompanyAdmin(s.role)?"Update hour meters":"View hour meters"}</a>`)}<div class="metrics four">${card("Service compliance",over?"Review":"On track","Based on current service thresholds")}${card("Due < 50 h",String(due),"Schedule before threshold")}${card("Overdue services",String(over),"Hour meter at / above service threshold")}${card("Open work orders","Use Operations","Existing work-order controls retained")}</div>${table("Maintenance planner","Hour-meter based service forecasting",["Fleet","Task","Due in","Risk","Responsible"],m.maintenance.map(x=>[esc(x.fleet),esc(x.task),`${Math.round(num(x.due))} h`,num(x.due)<=0?"Overdue":num(x.due)<50?"Due soon":"Plan","Workshop / Planner"]))}</section>`));}

async function production(env:Env,s:AdminSession){const d=await data(env,s),m=calc(d),target=num(d.settings?.dailyTarget),ach=target?m.tonnes/target*100:0;return html(shell("production","Production",s,`<section class="content">${head(`${s.companyName} / PRODUCTION`,"Production",`<a class="btn" href="/contractor?view=daily">${isCompanyAdmin(s.role)?"+ Add / import daily report":"View daily reports"}</a>`)}<div class="metrics four">${card("Today actual",`${fmt(m.tonnes,0)} t`,target?`${fmt(target,0)} t target`:"Set target in Company Setup")}${card("Achievement",target?pct(ach):"—","Daily production performance")}${card("Availability",pct(m.availability),"Latest loaded production date")}${card("Utilisation",pct(m.utilisation),"Operating ÷ available hours")}</div>${table("Daily production history","Production, availability inputs and downtime in the same record",["Date","Fleet","Target","Actual","Shift h","Operating h","Downtime h"],d.production.map(r=>[esc(r.reportDate),esc(r.fleet),target?`${fmt(target,0)} t/day`:"—",`${fmt(num(r.tonnes),0)} t`,fmt(num(r.shiftHours),1),fmt(num(r.operatingHours),1),fmt(num(r.plannedDowntime)+num(r.unplannedDowntime),1)]))}</section>`));}

async function reports(env:Env,s:AdminSession){const d=await data(env,s),m=calc(d),p=pareto(d.events),target=num(d.settings?.dailyTarget),monthTonnes=d.production.reduce((a,r)=>a+num(r.tonnes),0),totalDT=d.events.reduce((a,e)=>a+num(e.downtime),0),due=m.maintenance.filter(x=>num(x.due)<50).length;const max=Math.max(1,...p.map(x=>x[1]));
 return html(shell("reports-live","Reports",s,`<section class="content">${head(`${s.companyName} / REPORTS`,"Reports",`<a class="btn" href="/company-admin/export?format=xlsx&period=month">Export Excel</a><a class="btn" href="/contractor?view=reports-admin&type=monthly">Reports Centre</a>`)}<section class="reporthero"><div><small>MANAGEMENT REPORT · LIVE COMPANY DATA</small><h2>Monthly fleet performance report</h2><p>One management view combining production, reliability, maintenance compliance and the engineering actions that need attention.</p></div><button onclick="window.print()">Print / PDF</button></section><div class="metrics">${card("Average availability",pct(m.availability),`Target ≥ ${num(d.settings?.availabilityTarget,90).toFixed(0)}%`)}${card("Average utilisation",pct(m.utilisation),"Operational opportunity")}${card("Production loaded",`${fmt(monthTonnes,0)} t`,target?`Daily target ${fmt(target,0)} t`:"Target can be configured")}${card("Total downtime",`${totalDT.toFixed(1)} h`,`${d.events.length} recorded events`)}${card("Due < 50 h",String(due),"Maintenance attention")}</div><div class="grid2"><section class="panel"><div class="panelhead"><div><small>DOWNTIME PARETO</small><h2>Where downtime is being lost</h2></div><strong>${totalDT.toFixed(1)} h</strong></div>${p.length?p.map(([k,v])=>`<div class="pareto"><b>${esc(k)}</b><span><i style="width:${v/max*100}%"></i></span><strong>${v.toFixed(1)} h</strong></div>`).join(""):`<p class="empty">Breakdown data will build the Pareto.</p>`}<div class="insight"><b>Engineering focus:</b> prioritise the highest downtime systems, then verify repeat failures and maintenance compliance.</div></section><section class="panel"><div class="panelhead"><div><small>MANAGEMENT ACTIONS</small><h2>Recommended engineering actions</h2></div></div>${action(1,p[0]?`${p[0][0]} reliability campaign`:"Capture failure causes",p[0]?`Inspect recurring ${p[0][0]} failures and standardise corrective action.`:"More breakdown data is required to create a reliable Pareto.",p[0]?"HIGH":"MEDIUM")}${action(2,"Service compliance",`${due} service(s) are inside the 50 h planning window.`,due?"HIGH":"PLAN")}${action(3,"Utilisation improvement review",m.availability-m.utilisation>8?"Availability is stronger than utilisation. Analyse idle, queue, delay and operator-loss categories.":"Continue monitoring utilisation and availability together.")}</section></div><section class="panel reportlibrary"><div class="panelhead"><div><small>REPORT LIBRARY</small><h2>Operational and management reports</h2></div></div><div class="library"><a href="/contractor?view=daily"><b>Daily Operations Report</b><span>Daily production and downtime capture</span></a><a href="/contractor?view=reports-admin&type=weekly"><b>Weekly Fleet Summary</b><span>Weekly KPI reporting</span></a><a href="/contractor?view=reports-admin&type=monthly"><b>Monthly Management Report</b><span>Monthly review and publication</span></a><a href="/contractor?view=breakdowns"><b>Downtime Pareto</b><span>Failure-category analysis</span></a><a href="/contractor?view=maintenance"><b>Maintenance Compliance</b><span>Services due and overdue</span></a><a href="/contractor?view=fleet"><b>Machine History / Fleet</b><span>Fleet and hour-meter status</span></a></div></section></section>`));}

async function subscriptionRequest(req:Request,env:Env,s:AdminSession){await env.DB.prepare(`CREATE TABLE IF NOT EXISTS subscription_requests_v1(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL,account_id INTEGER NOT NULL,customer_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',note TEXT,created_at TEXT NOT NULL)`).run();if(req.method==="POST"){const f=await req.formData(),type=String(f.get("customerType")||"");if(!["Mine","Contractor"].includes(type))return redirect("/contractor?view=subscription-request&msg=Choose+Mine+or+Contractor");await env.DB.prepare("INSERT INTO subscription_requests_v1(company_id,account_id,customer_type,status,note,created_at) VALUES(?,?,?,?,?,?)").bind(s.companyId,s.accountId,type,"pending",String(f.get("note")||""),new Date().toISOString()).run();return redirect("/contractor?view=subscription-request&msg=Subscription+request+submitted")}
 const rows=await all(env,"SELECT customer_type customerType,status,note,created_at createdAt FROM subscription_requests_v1 WHERE company_id=? ORDER BY id DESC LIMIT 10",[s.companyId]);const url=new URL(req.url),msg=url.searchParams.get("msg")||"";return html(shell("subscription-request","Subscription Request",s,`<section class="content">${head(`${s.companyName} / SUBSCRIPTION`,"Subscription Request")} ${msg?`<div class="notice">${esc(msg)}</div>`:""}<section class="panel"><h2>Choose customer environment</h2><p class="muted">Select whether this company operates as a mining contractor or a mine. Pricing is provided by official Sindane Asset Solutions quotation.</p><form method="post" action="/contractor?view=subscription-request"><div class="choicegrid"><label><input type="radio" name="customerType" value="Contractor" required><b>Contractor</b><span>For contractor fleets, crews and single or multi-site operations.</span></label><label><input type="radio" name="customerType" value="Mine" required><b>Mine</b><span>For mine-owned fleets, mine sites and larger operational reporting requirements.</span></label></div><label class="field">Scope / note<textarea name="note" placeholder="Fleet size, sites, reporting requirements or onboarding notes"></textarea></label><button class="primary" type="submit">Submit subscription request</button></form></section>${table("Request history","Submitted company subscription requests",["Type","Status","Submitted","Note"],rows.map(r=>[esc(r.customerType),esc(r.status),esc(String(r.createdAt).slice(0,16)),esc(r.note||"")]))}</section>`));}

async function ensureRecommendations(env:Env){
 await env.DB.prepare(`CREATE TABLE IF NOT EXISTS engineering_recommendations_v1(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL,author_id INTEGER NOT NULL,author_name TEXT NOT NULL,fleet_number TEXT NOT NULL DEFAULT '',recommendation TEXT NOT NULL,priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'open',admin_response TEXT NOT NULL DEFAULT '',responded_by TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,assignee_name TEXT NOT NULL DEFAULT '',due_date TEXT NOT NULL DEFAULT '')`).run();
 const columns=await all(env,'PRAGMA table_info(engineering_recommendations_v1)');
 for(const name of ['assignee_name','due_date'])if(!columns.some(c=>c.name===name)){try{await env.DB.prepare(`ALTER TABLE engineering_recommendations_v1 ADD COLUMN ${name} TEXT NOT NULL DEFAULT ''`).run()}catch(error){if(!String(error).includes('duplicate column'))throw error}}
 await env.DB.prepare('CREATE INDEX IF NOT EXISTS engineering_recommendations_company ON engineering_recommendations_v1(company_id,id)').run();
}
async function recommendationRows(env:Env,s:AdminSession){await ensureRecommendations(env);return all(env,'SELECT * FROM engineering_recommendations_v1 WHERE company_id=? ORDER BY id DESC',[s.companyId]);}
async function recommendationSummary(env:Env,s:AdminSession){const rows=await recommendationRows(env,s);return `<section class="panel"><h2>Engineering recommendations</h2><p>${rows.filter(r=>r.status!=='completed').length} awaiting completion · ${rows.filter(r=>overdueRecommendation(r,todayLocal())).length} overdue · ${rows.filter(r=>r.status==='completed').length} completed</p><a class="btn" href="/contractor?view=recommendations">${isCompanyAdmin(s.role)?'Review and record action taken':'Add recommendations and track actions'}</a></section>`;}
async function recommendations(req:Request,env:Env,s:AdminSession){
 const rows=await recommendationRows(env,s),d=await data(env,s),admin=isCompanyAdmin(s.role),csrf=await sha256(getCookie(req));
 const machineOptions=`<option value="">Whole fleet</option>${d.machines.map(m=>`<option value="${esc(m.fleet)}">${esc(m.fleet)} · ${esc(m.site)}</option>`).join('')}`;
 const create=admin?'':`<section class="panel"><h2>Add engineering recommendation</h2><form method="post" action="/company-admin/recommendations"><input type="hidden" name="csrf" value="${csrf}"><input type="hidden" name="action" value="create"><label>Equipment<select name="fleet">${machineOptions}</select></label><label>Priority<select name="priority"><option value="normal">Normal</option><option value="high">High</option><option value="critical">Critical</option></select></label><label>Findings and recommended action<textarea name="recommendation" maxlength="4000" required></textarea></label><button class="primary">Save recommendation</button></form></section>`;
 const items=rows.map(r=>`<article><h3>${esc(r.fleet_number||'Whole fleet')} · ${esc(r.priority)} · ${esc(r.status)}</h3><small>${esc(r.author_name)} · ${esc(String(r.created_at).slice(0,16))}</small><p>${esc(r.recommendation)}</p><p>Responsible: ${esc(r.assignee_name||'Unassigned')} · Due: ${esc(r.due_date||'Not set')} ${overdueRecommendation(r,todayLocal())?'<strong>OVERDUE</strong>':''}</p>${r.admin_response?`<p><b>Admin action (${esc(r.responded_by)}):</b> ${esc(r.admin_response)}</p>`:''}${admin?`<form method="post" action="/company-admin/recommendations"><input type="hidden" name="csrf" value="${csrf}"><input type="hidden" name="id" value="${num(r.id)}"><input type="hidden" name="action" value="respond"><label>Progress<select name="status">${['open','in-progress','completed'].map(v=>`<option ${r.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Responsible person<input name="assigneeName" maxlength="120" value="${esc(r.assignee_name)}"></label><label>Due date<input type="date" name="dueDate" value="${esc(r.due_date)}"></label><label>Response / action taken<textarea name="response" maxlength="4000" required>${esc(r.admin_response)}</textarea></label><button class="primary">Save action and progress</button></form>`:num(r.author_id)===s.accountId?`<form method="post" action="/company-admin/recommendations"><input type="hidden" name="csrf" value="${csrf}"><input type="hidden" name="id" value="${num(r.id)}"><input type="hidden" name="action" value="edit"><label>Update recommendation<textarea name="recommendation" maxlength="4000" required>${esc(r.recommendation)}</textarea></label><button class="primary">Update my recommendation</button></form>`:''}</article>`).join('');
 const msg=new URL(req.url).searchParams.get('msg');
 return html(shell('recommendations','Engineering Recommendations',s,`<section class="content recommendations">${head(s.companyName,'Engineering Recommendations')}<p>Engineers record findings and recommendations. Admin records the response, action taken and progress.</p>${msg?`<div class="notice">${esc(msg)}</div>`:''}${create}<section class="panel"><h2>Recommendations and action progress</h2>${items||'<p>No recommendations yet.</p>'}</section></section>`).replace('</head>',analyticsStyle+'</head>'));
}
export async function handleEngineeringActions(req:Request,env:Env):Promise<Response|null>{
 const path=new URL(req.url).pathname;if(!['/company-admin/recommendations','/company-admin/analytics-settings'].includes(path))return null;
 if(req.method!=='POST')return new Response('Method not allowed',{status:405});
 const s=await session(req,env);if(!s)return new Response('Sign in required',{status:401});
 if(!isCompanyAdmin(s.role)&&s.role!=='engineer')return new Response('Access denied',{status:403});
 const origin=req.headers.get('origin');if(origin&&origin!==new URL(req.url).origin)return new Response('Invalid request origin',{status:403});
 const f=await req.formData();if(String(f.get('csrf')||'')!==await sha256(getCookie(req)))return new Response('Invalid request token',{status:403});
 if(path==='/company-admin/analytics-settings'){
  if(!isCompanyAdmin(s.role))return new Response('Company Admin authority required',{status:403});
  const raw=String(f.get('rate')||'').trim(),rate=Number(raw);if(!raw||!Number.isFinite(rate)||rate<0||rate>1e9)return new Response('Enter a valid non-negative hourly rate',{status:400});
  await analyticsRate(env,s);await env.DB.prepare('INSERT INTO company_analytics_settings_v1(company_id,cost_per_hour,updated_by,updated_at) VALUES(?,?,?,?) ON CONFLICT(company_id) DO UPDATE SET cost_per_hour=excluded.cost_per_hour,updated_by=excluded.updated_by,updated_at=excluded.updated_at').bind(s.companyId,rate,s.accountId,new Date().toISOString()).run();return redirect('/contractor');
 }
 await ensureRecommendations(env);
 const action=String(f.get('action')||''),id=num(f.get('id')),text=String(f.get('recommendation')||'').trim(),now=new Date().toISOString();
 if(action==='create'&&s.role==='engineer'){
   const fleet=String(f.get('fleet')||''),priority=String(f.get('priority')||'normal');
   if(!text||text.length>4000||!['normal','high','critical'].includes(priority))return new Response('Enter a recommendation and valid priority',{status:400});
   if(fleet&&!await first(env,'SELECT id FROM machines WHERE company_id=? AND fleet_number=?',[s.companyId,fleet]))return new Response('Equipment not found',{status:400});
   await env.DB.prepare('INSERT INTO engineering_recommendations_v1(company_id,author_id,author_name,fleet_number,recommendation,priority,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)').bind(s.companyId,s.accountId,s.fullName,fleet,text,priority,now,now).run();
 }else if(action==='edit'&&s.role==='engineer'){
   if(!text||text.length>4000)return new Response('Enter a recommendation up to 4000 characters',{status:400});
   if(!await first(env,'SELECT id FROM engineering_recommendations_v1 WHERE id=? AND company_id=? AND author_id=?',[id,s.companyId,s.accountId]))return new Response('Recommendation not found',{status:404});
   await env.DB.prepare('UPDATE engineering_recommendations_v1 SET recommendation=?,updated_at=? WHERE id=? AND company_id=? AND author_id=?').bind(text,now,id,s.companyId,s.accountId).run();
 }else if(action==='respond'&&isCompanyAdmin(s.role)){
   const status=String(f.get('status')||''),response=String(f.get('response')||'').trim(),assignee=String(f.get('assigneeName')||'').trim(),due=String(f.get('dueDate')||'');
   if(assignee.length>120||(due&&(!/^\d{4}-\d{2}-\d{2}$/.test(due)||!Number.isFinite(Date.parse(due))||new Date(due).toISOString().slice(0,10)!==due)))return new Response('Enter a valid responsible person and due date',{status:400});
   if(!['open','in-progress','completed'].includes(status)||!response||response.length>4000)return new Response('Enter a response and valid progress status',{status:400});
   if(!await first(env,'SELECT id FROM engineering_recommendations_v1 WHERE id=? AND company_id=?',[id,s.companyId]))return new Response('Recommendation not found',{status:404});
   await env.DB.prepare('UPDATE engineering_recommendations_v1 SET status=?,admin_response=?,responded_by=?,updated_at=?,assignee_name=?,due_date=? WHERE id=? AND company_id=?').bind(status,response,s.fullName,now,assignee,due,id,s.companyId).run();
 }else return new Response('This action is not permitted for your role',{status:403});
 return redirect('/contractor?view=recommendations&msg=Saved+successfully');
}
export async function guardEngineerWrites(req:Request,env:Env):Promise<Response|null>{
 if(['GET','HEAD','OPTIONS'].includes(req.method))return null;
 const path=new URL(req.url).pathname;
 if(['/api/contractor/logout','/api/contractor/login','/contractor-login','/contractor-logout','/tmm-assistant'].includes(path)||path.startsWith('/owner'))return null;
 // Block legacy write routes too: hiding capture forms is not an authorization check.
 const s=await session(req,env);
 return s?.role==='engineer'?new Response('Engineers can analyse records and add recommendations. Company Admin authority is required to change source data.',{status:403,headers:{'cache-control':'private, no-store'}}):null;
}

const todayLocal=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Johannesburg',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
async function dailyRows(env:Env,s:AdminSession){return all(env,'SELECT id,report_date reportDate,fleet_number fleet,activity,capture_basis captureBasis,hour_meter_start hourMeterStart,hour_meter_end hourMeterEnd,duration_hours duration,tonnes,fault_reason faultReason,breakdown_start breakdownStart,breakdown_end breakdownEnd FROM daily_reports_v3 WHERE company_id=? ORDER BY report_date,id',[s.companyId]);}
async function analyticsRate(env:Env,s:AdminSession){await env.DB.prepare('CREATE TABLE IF NOT EXISTS company_analytics_settings_v1(company_id INTEGER PRIMARY KEY,cost_per_hour REAL NOT NULL DEFAULT 0,updated_by INTEGER NOT NULL,updated_at TEXT NOT NULL)').run();return num((await first(env,'SELECT cost_per_hour rate FROM company_analytics_settings_v1 WHERE company_id=?',[s.companyId]))?.rate);}
function reliabilityPanel(d:Awaited<ReturnType<typeof data>>,f:ReturnType<typeof dashboardFilters>){
 const fleets=new Set(d.machines.filter(m=>(!f.site||m.site===f.site)&&(!f.fleet||m.fleet===f.fleet)).map(m=>m.fleet));
 const allowed=(r:Row)=>(!f.site||fleets.has(r.fleet))&&(!f.fleet||r.fleet===f.fleet);
 const production=d.production.filter(allowed),events=d.events.filter(allowed),r=reliability(production,events,f.from,f.to),trend=reliabilityTrend(production,events,f.from,f.to);
 return `<section class="panel"><h2>Reliability indicators</h2><p>MTBF = recorded operating hours ÷ breakdowns opened in the period. MTTR = recorded downtime for closed breakdowns ÷ repairs closed in the period. Complete hours and fault records are required.</p><div class="metrics four">${card('MTBF',r.mtbf==null?'—':fmt(r.mtbf)+' h',`${r.failures} failures · ${fmt(r.operating)} recorded operating hours`)}${card('MTTR',r.mttr==null?'—':fmt(r.mttr)+' h',`${r.repairs} closed repairs`)}</div></section><div class="grid2">${chart('Monthly MTBF trend',trend.map(t=>t.month),[{name:'MTBF',color:'#2563eb',values:trend.map(t=>t.mtbf)}],'line',' h')}${chart('Monthly MTTR trend',trend.map(t=>t.month),[{name:'MTTR',color:'#d97706',values:trend.map(t=>t.mttr)}],'line',' h')}</div>`;
}
async function qualityPage(req:Request,env:Env,s:AdminSession){const d=await data(env,s),daily=await dailyRows(env,s),issues=qualityIssues(d.production,daily);return html(shell('data-quality','Data Quality',s,`<section class="content">${head(s.companyName,'Data Quality')}<section class="panel"><p>Review flags before correcting records. Multiple shift captures may be legitimate, and meter replacements may explain decreasing readings. No records are deleted or changed by these checks.</p><p>${issues.length} review flags across company records.</p>${isCompanyAdmin(s.role)?'<a class="btn" href="/contractor?view=daily">Review daily reports</a>':'<a class="btn" href="/contractor?view=recommendations">Request an Admin correction</a>'}</section>${table('Records requiring review','Checks cover duplicate totals/captures, hour meters and shift hours',['Date','Machine','Record','Review flag'],issues.map(r=>[esc(r.date),esc(r.fleet),esc(r.record),esc(r.issue)]))}</section>`));}
