async function machineHistory(req:Request,env:Env,s:AdminSession){
 const d=await data(env,s),url=new URL(req.url),fleet=url.searchParams.get('fleet')||'',machine=d.machines.find(m=>m.fleet===fleet);
 const select=`<form method="get" class="panel dashboard-filters" action="/contractor"><input type="hidden" name="view" value="machine-history"><label>Equipment<select name="fleet" required><option value="">Select equipment</option>${d.machines.map(m=>`<option value="${esc(m.fleet)}" ${m.fleet===fleet?'selected':''}>${esc(m.fleet)} · ${esc(m.site)}</option>`).join('')}</select></label><button class="primary">Open history</button></form>`;
 if(fleet&&!machine)return html('Equipment not found in this company.',404);
 let content='';
 if(machine){const events=d.events.filter(e=>e.fleet===fleet),recommendations=(await recommendationRows(env,s)).filter(r=>r.fleet_number===fleet),work=await all(env,'SELECT title,status,due_at dueAt,assigned_to assignedTo FROM work_orders WHERE company_id=? AND fleet_number=? ORDER BY id DESC',[s.companyId,fleet]);
 const historyUrl=new URL(req.url);if(!url.searchParams.has('from'))historyUrl.searchParams.set('from','1900-01-01');const f=dashboardFilters(historyUrl);
 content=`<section class="panel"><h2>Machine identity · ${esc(fleet)}</h2><p>Type: ${esc(machine.category)} · Site: ${esc(machine.site)}</p><p>Current registered hour meter: ${fmt(num(machine.hours))} h</p><p><a href="/contractor?view=fleet">Review machine registration</a></p></section><section class="panel"><h2>Operating history</h2><p>Live engine-hour and ignition history will be displayed only when authorised machine readings arrive. Registered meter values are not presented as live telemetry.</p><p><a class="btn" href="/telemetry">Open received machine readings</a></p></section><section class="panel"><h2>Machine condition</h2><p>Fuel, coolant, hydraulic and engine sensor values will be shown when supported by the connected source. Missing sensor readings remain unavailable.</p><p><a href="/telemetry/connections">Review telemetry connections</a></p></section>${table('Fault history','Recorded breakdown and service events',['Type','Opened','Closed','System','Description','Hours','Status'],events.map(e=>[esc(e.eventType),esc(e.openedAt),esc(e.closedAt),esc(e.system),esc(e.description),esc(e.downtime),esc(e.status)]))}<section class="panel"><h2>Service planning</h2><p>${machine.nextService==null?'Next service threshold is not configured.':`Next service: ${fmt(num(machine.nextService))} h · ${fmt(num(machine.nextService)-num(machine.hours))} h remaining against registered meter`}</p><p>Service planning uses the registered meter until verified telemetry is available.</p><p><a href="/contractor?view=fleet">Review service settings</a></p></section>${table('Maintenance work history','Recorded work orders and current progress',['Work','Status','Due','Assigned to'],work.map(w=>[esc(w.title),esc(w.status),esc(w.dueAt),esc(w.assignedTo)]))}${table('Engineering recommendations','Recommendations for this equipment',['Findings','Progress','Responsible','Due','Admin action'],recommendations.map(r=>[esc(r.recommendation),esc(r.status),esc(r.assignee_name),esc(r.due_date),esc(r.admin_response)]))}<section class="panel"><h2>Machine reports</h2><p>Engineering reliability calculations use only recorded operating hours and failures. Unavailable metrics remain blank.</p>${reliabilityPanel(d,{...f,fleet})}<p><a class="btn" href="/contractor?view=reports">Open company reports</a> <button type="button" onclick="window.print()">Print machine history</button></p></section>`;
 }
 return html(shell('machine-history','Machine History',s,`<section class="content machine-history-page">${head(s.companyName,'Machine History')}${select}${content||`<section class="panel"><h2>${d.machines.length?'Choose a machine to inspect its history':'Machine history workspace is ready'}</h2><p>${d.machines.length?'Select a registered machine above to see its condition and history.':'No equipment is registered yet. We are building the structure first; demonstration data is not required now.'}</p><p>Once machines are registered and authorised telemetry arrives, this workspace will show the available readings and service information.</p><p><a class="btn" href="/contractor?view=fleet">Register or review machines</a> <a class="btn" href="/telemetry/connections">Connect machine telemetry</a></p></section><section class="panel"><h2>Machine history modules</h2><div class="machine-history-modules"><div class="machine-history-module"><b>01 · Machine identity</b><p>Equipment ID, type and site from registration.</p></div><div class="machine-history-module"><b>02 · Operating history</b><p>Received engine-hour and ignition observations.</p></div><div class="machine-history-module"><b>03 · Machine condition</b><p>Fuel, coolant, hydraulic and engine sensor readings where supported.</p></div><div class="machine-history-module"><b>04 · Fault history</b><p>Received fault codes, severity and occurrence times.</p></div><div class="machine-history-module"><b>05 · Service planning</b><p>Service threshold and hours remaining from valid meter readings.</p></div><div class="machine-history-module"><b>06 · Reports</b><p>Machine trends, verified alerts and engineering history.</p></div></div><p>Missing readings remain unavailable. Production, downtime and fuel usage are not inferred from engine hours alone.</p><p><a href="/telemetry">View machine readings</a> · <a href="/telemetry/connections">Connect machine data</a></p></section>`}</section>`).replace('</head>',analyticsStyle+machineHistoryLayoutStyle+'</head>'));
}

