export default {
 async fetch(req:Request,env:Env,ctx:ExecutionContext):Promise<Response>{
  const url=new URL(req.url);
  if(url.pathname==="/contractor"){
   const s=await session(req,env);
   if(s&&canViewCompanyPage(low(s.role),url.searchParams.get("view")||"dashboard")){
    const view=url.searchParams.get("view")||"dashboard";
    if(view==="machine-history"&&req.method==="GET")return machineHistory(req,env,s);
    if(view==="data-quality"&&req.method==="GET")return qualityPage(req,env,s);
    if(view==="management-presentation"&&req.method==="GET"){const d=await data(env,s),rows=await recommendationRows(env,s),rate=await analyticsRate(env,s);return html(shell(view,"Management Presentation",s,managementHtml(req,d,rows,rate,s.companyName,todayLocal())));}
    if(view==="recommendations"&&req.method==="GET")return recommendations(req,env,s);
    if(view==="dashboard"&&req.method==="GET")return dashboard(req,env,s);
    if(view==="breakdowns"&&req.method==="GET")return breakdowns(env,s);
    if(view==="maintenance"&&req.method==="GET")return maintenance(env,s);
    if(view==="production"&&req.method==="GET")return production(env,s);
    if(view==="reports-live"&&req.method==="GET")return reports(env,s);
    if(view==="subscription-request"&&isCompanyAdmin(low(s.role)))return subscriptionRequest(req,env,s);
   }
  }
  return currentApp.fetch(req,env as never,ctx as never);
 },
 async scheduled(controller:ScheduledController,env:Env,ctx:ExecutionContext){return currentApp.scheduled(controller as never,env as never,ctx as never);}
};
